<?php require_once __DIR__ . '/includes/config.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check();$s=db()->prepare('SELECT * FROM users WHERE username=?');$s->execute([trim($_POST['username'])]);$u=$s->fetch();if($u&&password_verify($_POST['password'],$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'full_name'=>$u['full_name'],'username'=>$u['username'],'role'=>$u['role']];log_action('LOGIN');header('Location:index.php');exit;}$err='Invalid username or password';}head('Login');?><section class="login"><h1>Ghost Worker Detection System</h1><p><?=e($err)?></p><form method="post"><input type="hidden" name="token" value="<?=e(token())?>"><label>Username</label><input name="username" required><label>Password</label><input type="password" name="password" required><button>Sign in</button></form></section><?php foot();?>